const weatherPoints=@json($weatherMapData),weatherMap=L.map('globalWeatherMap',{worldCopyJump:true,preferCanvas:true}).setView([18,12],2);L.tileLayer('https://{s}.basemaps.cartocdn.com/light_all/{z}/{x}/{y}{r}.png',{maxZoom:18,attribution:'&copy; OpenStreetMap &copy; CARTO'}).addTo(weatherMap);const weatherLayers={observations:L.layerGroup().addTo(weatherMap),rain:L.layerGroup().addTo(weatherMap),storm:L.layerGroup().addTo(weatherMap),wind:L.layerGroup().addTo(weatherMap)},layerEnabled={rain:true,storm:true,wind:true};const escapeWeather=s=>String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));function popupWeather(p){const alerts=[p.rain?'<b class="rain">Rain</b>':'',p.storm?'<b class="storm">Storm</b>':'',p.strong_wind?'<b class="wind">Strong wind</b>':''].join('');return `<div class="weather-popup"><h4>${escapeWeather(p.flag)} ${escapeWeather(p.name)}</h4><span>${escapeWeather(p.capital||'National observation')} · ${escapeWeather(p.observed_at||'latest')}</span><div class="weather-popup-grid"><div><small>Temperature</small><strong>${p.temperature.toFixed(1)}°C</strong></div><div><small>Precipitation</small><strong>${p.precipitation.toFixed(1)} mm</strong></div><div><small>Wind</small><strong>${p.wind.toFixed(1)} km/h</strong></div><div><small>Wind gust</small><strong>${p.gust.toFixed(1)} km/h</strong></div></div><div class="weather-alerts">${alerts||'<b>Normal conditions</b>'}</div></div>`}let observationMarkers=[];function rebuildWeatherLayers(code=''){Object.values(weatherLayers).forEach(layer=>layer.clearLayers());observationMarkers=[];const visible=weatherPoints.filter(p=>!code||p.code===code);visible.forEach(p=>{const popup=popupWeather(p),base=L.circleMarker([p.lat,p.lon],{radius:3,color:'#7189a1',weight:1,fillColor:'#a8b8c8',fillOpacity:.5}).bindPopup(popup);weatherLayers.observations.addLayer(base);observationMarkers.push({code:p.code,marker:base,point:p});if(p.rain)L.circleMarker([p.lat,p.lon],{radius:Math.min(13,6+p.precipitation),color:'#fff',weight:1.5,fillColor:'#1684ff',fillOpacity:.78}).bindPopup(popup).addTo(weatherLayers.rain);if(p.storm)L.circleMarker([p.lat,p.lon],{radius:11,color:'#fff',weight:2,fillColor:'#8a5cff',fillOpacity:.88}).bindPopup(popup).addTo(weatherLayers.storm);if(p.strong_wind)L.circleMarker([p.lat,p.lon],{radius:Math.min(14,6+p.wind/15),color:'#fff',weight:1.5,fillColor:'#ef8d22',fillOpacity:.82}).bindPopup(popup).addTo(weatherLayers.wind)});Object.keys(layerEnabled).forEach(key=>{if(layerEnabled[key]&&!weatherMap.hasLayer(weatherLayers[key]))weatherMap.addLayer(weatherLayers[key]);if(!layerEnabled[key]&&weatherMap.hasLayer(weatherLayers[key]))weatherMap.removeLayer(weatherLayers[key])});document.getElementById('weatherVisibleCount').textContent=visible.length;document.getElementById('rainLayerCount').textContent=visible.filter(p=>p.rain).length;document.getElementById('stormLayerCount').textContent=visible.filter(p=>p.storm).length;document.getElementById('windLayerCount').textContent=visible.filter(p=>p.strong_wind).length;if(code&&visible.length){weatherMap.setView([visible[0].lat,visible[0].lon],5);observationMarkers[0].marker.openPopup()}else weatherMap.setView([18,12],2)}document.querySelectorAll('[data-weather-layer]').forEach(button=>button.addEventListener('click',()=>{const key=button.dataset.weatherLayer;layerEnabled[key]=!layerEnabled[key];button.classList.toggle('active',layerEnabled[key]);if(layerEnabled[key])weatherMap.addLayer(weatherLayers[key]);else weatherMap.removeLayer(weatherLayers[key])}));const countryFilter=document.getElementById('weatherCountryFilter');countryFilter.addEventListener('change',()=>rebuildWeatherLayers(countryFilter.value));document.getElementById('resetWeatherMap').addEventListener('click',()=>{countryFilter.value='';rebuildWeatherLayers()});rebuildWeatherLayers(new URLSearchParams(location.search).get('country')||'');
