<script>
// Replace the light legacy tiles with a labelled dark basemap.
const weatherDarkBasemap = L.tileLayer(
    'https://{s}.basemaps.cartocdn.com/dark_all/{z}/{x}/{y}{r}.png',
    { maxZoom: 19, subdomains: 'abcd', attribution: '&copy; OpenStreetMap contributors &copy; CARTO' }
).addTo(weatherMap);
weatherMap.eachLayer(layer => {
    if (layer instanceof L.TileLayer && layer !== weatherDarkBasemap) weatherMap.removeLayer(layer);
});
L.control.scale({ imperial: false, position: 'bottomright' }).addTo(weatherMap);

const weatherStage = document.querySelector('.weather-map-stage');
const weatherFullscreen = document.getElementById('weatherMapFullscreen');
weatherFullscreen?.addEventListener('click', async () => {
    try {
        if (document.fullscreenElement === weatherStage) await document.exitFullscreen();
        else await weatherStage.requestFullscreen();
    } catch (error) {
        console.error('Weather map fullscreen is unavailable', error);
    }
});
document.addEventListener('fullscreenchange', () => {
    const active = document.fullscreenElement === weatherStage;
    weatherFullscreen?.querySelector('i')?.classList.toggle('fa-expand', !active);
    weatherFullscreen?.querySelector('i')?.classList.toggle('fa-compress', active);
    if (weatherFullscreen) weatherFullscreen.lastChild.textContent = active ? ' Exit' : ' Fullscreen';
    setTimeout(() => weatherMap.invalidateSize(), 180);
});

const hubSearch = document.getElementById('hubSearch');
const hubCards = [...document.querySelectorAll('.city-card')];
const applyHubSearch = () => {
    const query = hubSearch.value.toLocaleLowerCase().trim();
    let visible = 0;
    hubCards.forEach(card => {
        const match = !query || card.textContent.toLocaleLowerCase().includes(query);
        card.hidden = !match;
        if (match) visible++;
    });
    document.getElementById('hubVisibleCount').textContent = visible;
};
hubSearch?.addEventListener('input', applyHubSearch);
</script>
