<script>
new Chart(document.getElementById('weatherRiskChart'),{type:'doughnut',data:{datasets:[{data:[{{ $weatherData->where('risk_level','Low')->count() }},{{ $weatherData->where('risk_level','Medium')->count() }},{{ $weatherData->where('risk_level','High')->count() }}],backgroundColor:['#19ad60','#edae19','#e84654'],borderWidth:0}]},options:{maintainAspectRatio:false,cutout:'72%',plugins:{legend:{display:false}},events:[]}});

const countrySearch=document.getElementById('hubSearch');
const countryCards=[...document.querySelectorAll('.city-card')];
const loadMoreButton=document.getElementById('loadMoreCountries');
const resultSummary=document.getElementById('countryResultSummary');
const countryFlagCodes=@json($weatherData->mapWithKeys(fn ($weather) => [$weather['name'] => strtolower($weather['code'])]));
let countryLimit=24;

countryCards.forEach(card=>{
    const countryName=card.querySelector('.city-head h3')?.textContent.trim();
    const code=countryFlagCodes[countryName];
    const icon=card.querySelector('.weather-icon');
    if(!code||!icon)return;
    const weatherSymbol=icon.querySelector('i')?.cloneNode(true);
    icon.classList.add('country-flag-mark');
    icon.innerHTML=`<img src="https://flagcdn.com/w80/${code}.png" alt="Flag of ${countryName}" loading="lazy">`;
    if(weatherSymbol){const badge=document.createElement('span');badge.className='condition-badge';badge.appendChild(weatherSymbol);icon.appendChild(badge)}
});

function renderCountryDirectory(reset=false){
    if(reset)countryLimit=24;
    const query=(countrySearch?.value||'').toLocaleLowerCase().trim();
    const matches=countryCards.filter(card=>!query||card.textContent.toLocaleLowerCase().includes(query));
    countryCards.forEach(card=>card.hidden=true);
    matches.slice(0,countryLimit).forEach(card=>card.hidden=false);
    const shown=Math.min(countryLimit,matches.length);
    document.getElementById('hubVisibleCount').textContent=matches.length;
    resultSummary.textContent=`Showing ${shown.toLocaleString('id-ID')} of ${matches.length.toLocaleString('id-ID')} countries`;
    loadMoreButton.hidden=shown>=matches.length;
}
countrySearch?.addEventListener('input',()=>renderCountryDirectory(true));
loadMoreButton?.addEventListener('click',()=>{countryLimit+=24;renderCountryDirectory()});
renderCountryDirectory();
</script>
@stop
